package main

import (
	"fmt"
	"math/rand"
	"os"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

const (
	gridWidth  = 20
	gridHeight = 15
	tickInterval = 150 * time.Millisecond
)

type Point struct {
	X, Y int
}

type Direction int

const (
	DirUp Direction = iota
	DirDown
	DirLeft
	DirRight
)

type GameState int

const (
	StatePlaying GameState = iota
	StateGameOver
)

type model struct {
	snake    []Point
	food     Point
	dir      Direction
	nextDir  Direction
	state    GameState
	score    int
	width    int
	height   int
}

func (m model) Init() tea.Cmd {
	return tickCmd()
}

func tickCmd() tea.Cmd {
	return tea.Tick(tickInterval, func(t time.Time) tea.Msg {
		return tickMsg{}
	})
}

type tickMsg struct{}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		switch msg.String() {
		case "ctrl+c", "q":
			return m, tea.Quit
		case "up", "w":
			if m.dir != DirDown {
				m.nextDir = DirUp
			}
		case "down", "s":
			if m.dir != DirUp {
				m.nextDir = DirDown
			}
		case "left", "a":
			if m.dir != DirRight {
				m.nextDir = DirLeft
			}
		case "right", "d":
			if m.dir != DirLeft {
				m.nextDir = DirRight
			}
		case "r", "enter":
			if m.state == StateGameOver {
				m = newModel(m.width, m.height)
				return m, tickCmd()
			}
		}

	case tickMsg:
		if m.state == StatePlaying {
			m.dir = m.nextDir
			head := m.snake[0]
			var newHead Point
			switch m.dir {
			case DirUp:
				newHead = Point{head.X, head.Y - 1}
			case DirDown:
				newHead = Point{head.X, head.Y + 1}
			case DirLeft:
				newHead = Point{head.X - 1, head.Y}
			case DirRight:
				newHead = Point{head.X + 1, head.Y}
			}

			// Wall collision
			if newHead.X < 0 || newHead.X >= m.width || newHead.Y < 0 || newHead.Y >= m.height {
				m.state = StateGameOver
				return m, nil
			}

			// Self collision
			for _, p := range m.snake {
				if p == newHead {
					m.state = StateGameOver
					return m, nil
				}
			}

			// Move snake
			m.snake = append([]Point{newHead}, m.snake...)

			// Check food
			if newHead == m.food {
				m.score++
				m.food = randomFood(m.width, m.height, m.snake)
			} else {
				m.snake = m.snake[:len(m.snake)-1]
			}

			return m, tickCmd()
		}
	}

	return m, nil
}

func randomFood(w, h int, snake []Point) Point {
	for {
		p := Point{rand.Intn(w), rand.Intn(h)}
		collision := false
		for _, s := range snake {
			if s == p {
				collision = true
				break
			}
		}
		if !collision {
			return p
		}
	}
}

var (
	snakeStyle  = lipgloss.NewStyle().Background(lipgloss.Color("#00ff00"))
	foodStyle   = lipgloss.NewStyle().Background(lipgloss.Color("#ff0000"))
	emptyStyle  = lipgloss.NewStyle().Background(lipgloss.Color("#1a1a2e"))
	headStyle   = lipgloss.NewStyle().Background(lipgloss.Color("#00cc00"))
	wallStyle   = lipgloss.NewStyle().Background(lipgloss.Color("#16213e"))
	scoreStyle  = lipgloss.NewStyle().Foreground(lipgloss.Color("#00ff00")).Bold(true)
	titleStyle  = lipgloss.NewStyle().Foreground(lipgloss.Color("#00ff00")).Bold(true).MarginBottom(1)
	gameOverStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("#ff4444")).Bold(true)
)

func (m model) View() string {
	var s string

	s += titleStyle.Render("🐍 贪吃蛇 Snake Game") + "\n"
	s += scoreStyle.Render(fmt.Sprintf("Score: %d", m.score)) + "\n\n"

	// Draw top border
	for x := 0; x < m.width+2; x++ {
		s += wallStyle.Render("  ")
	}
	s += "\n"

	for y := 0; y < m.height; y++ {
		// Left border
		s += wallStyle.Render("  ")

		for x := 0; x < m.width; x++ {
			p := Point{x, y}
			isSnake := false
			isHead := false
			for i, sp := range m.snake {
				if sp == p {
					isSnake = true
					if i == 0 {
						isHead = true
					}
					break
				}
			}
			switch {
			case isHead:
				s += headStyle.Render("  ")
			case isSnake:
				s += snakeStyle.Render("  ")
			case p == m.food:
				s += foodStyle.Render("  ")
			default:
				s += emptyStyle.Render("  ")
			}
		}

		// Right border
		s += wallStyle.Render("  ")
		s += "\n"
	}

	// Draw bottom border
	for x := 0; x < m.width+2; x++ {
		s += wallStyle.Render("  ")
	}
	s += "\n\n"

	s += lipgloss.NewStyle().Foreground(lipgloss.Color("#888888")).Render(
		"Arrow keys / WASD: Move  |  R/Enter: Restart  |  Q: Quit",
	) + "\n"

	if m.state == StateGameOver {
		s += "\n" + gameOverStyle.Render(fmt.Sprintf("💀 Game Over! Final Score: %d", m.score)) + "\n"
		s += lipgloss.NewStyle().Foreground(lipgloss.Color("#888888")).Render("Press R or Enter to restart") + "\n"
	}

	return s
}

func newModel(w, h int) model {
	centerX := w / 2
	centerY := h / 2
	snake := []Point{
		{centerX, centerY},
		{centerX - 1, centerY},
		{centerX - 2, centerY},
	}
	food := randomFood(w, h, snake)
	return model{
		snake:  snake,
		food:   food,
		dir:    DirRight,
		nextDir: DirRight,
		state:  StatePlaying,
		score:  0,
		width:  w,
		height: h,
	}
}

func main() {
	rand.Seed(time.Now().UnixNano())

	m := newModel(gridWidth, gridHeight)
	p := tea.NewProgram(m, tea.WithAltScreen())

	if _, err := p.Run(); err != nil {
		fmt.Println("Error running game:", err)
		os.Exit(1)
	}
}

// 本文件集中定义 Bubble Tea TUI 的状态类型、内部消息和模型切换向导数据结构。
package bubble

import (
	"context"
	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/bubbles/viewport"
	"gocode/internal/loop"
	"gocode/internal/model"
	"gocode/internal/settings"
	"gocode/internal/subagent"
	"gocode/internal/ui"
	"time"
)

// entryKind 表示 transcript 中一条消息的来源类别。
type entryKind int

// transcript 条目类型常量。
const (
	// entrySystem 表示系统状态或命令提示消息。
	entrySystem entryKind = iota
	// entryUser 表示用户输入消息。
	entryUser
	// entryAssistant 表示 assistant 的模型输出消息。
	entryAssistant
	// entryThinking 表示模型 thinking 过程消息。
	entryThinking
	// entryTool 表示工具调用、工具结果或终端命令消息。
	entryTool
	// entryError 表示错误消息。
	entryError
)

// transcriptEntry 是聊天历史区的一条可渲染记录。
type transcriptEntry struct {
	kind      entryKind
	title     string
	body      string
	color     string // 可选：标题颜色（lipgloss 颜色字符串），与 subagents 面板保持一致
	isError   bool // true for tool results with IsError=true
	toolUseID string
	toolName  string
	citations []toolCitation
	createdAt time.Time
}

type toolCitation struct {
	toolUseID string
	name      string
	target    string
	status    string
	preview   string
	isError   bool
}

// selectionPoint 表示 transcript 渲染结果中的一个显示单元格坐标。
type selectionPoint struct {
	row int
	col int
}

// assistantDeltaMsg 表示模型流式输出的一段文本增量。
type assistantDeltaMsg string

// thinkingDeltaMsg 表示模型 thinking 流式输出的一段文本增量。
type thinkingDeltaMsg string

// toolCallMsg 表示工具调用事件。
type toolCallMsg ui.ToolCallEvent

// toolResultMsg 表示工具结果事件。
type toolResultMsg ui.ToolResultEvent

// systemEventMsg 表示后台任务等系统事件。
type systemEventMsg ui.SystemEvent

// doneMsg 表示当前 assistant 输出已经结束。
type doneMsg struct{}

// turnFinishedMsg 表示一轮模型调用已经结束，并携带可能的错误。
type turnFinishedMsg struct{ err error }

// shellFinishedMsg 表示一次终端命令执行完成后的结果。
type shellFinishedMsg struct {
	command string
	stdout  string
	stderr  string
	err     error
}

type subagentFinishedMsg struct {
	result subagent.Result
	err    error
}

// cursorFrameMsg 驱动自定义光标动画更新一帧。
type cursorFrameMsg time.Time

// modelWizardStep 表示 /model 向导当前所处的步骤。
type modelWizardStep int

// /model 向导步骤常量。
const (
	// modelWizardProvider 表示正在选择 provider。
	modelWizardProvider modelWizardStep = iota
	// modelWizardConfirm 表示正在确认将要应用的模型配置。
	modelWizardConfirm
)

// modelProviderOption 描述 /model 向导中的一个 provider 选项。
type modelProviderOption struct {
	id          string
	label       string
	description string
}

// modelProviderOptions 是当前 TUI 支持切换的 provider 列表。
var modelProviderOptions = []modelProviderOption{
	{
		id:          model.ProviderCustom,
		label:       "custom",
		description: "Local or custom OpenAI-compatible endpoint",
	},
	{
		id:          model.ProviderDeepSeek,
		label:       "deepseek",
		description: "DeepSeek official OpenAI-compatible endpoint",
	},
}

// modelWizard 保存 /model 交互向导的临时 UI 状态。
type modelWizard struct {
	step          modelWizardStep
	selectedIndex int
	err           string
}

type settingWizardStep int

const (
	settingWizardContext settingWizardStep = iota
	settingWizardRunMode
	settingWizardMeterLocation
	settingWizardLimit
	settingWizardConfirm
)

type settingOption struct {
	label       string
	description string
	apply       func(*settings.Config)
}

type settingWizard struct {
	step     settingWizardStep
	selected map[settingWizardStep]int
	draft    settings.Config
	err      string
}

// contextMeterAnimation 记录 context 进度条从旧 token 用量跳到新用量的短时动画。
type contextMeterAnimation struct {
	initialized bool
	startedAt   time.Time
	fromUsed    float64
	fromCache   float64
	targetUsed  int
	targetCache int
}

// newModelWizard 根据当前配置创建 provider 选择向导，并默认选中当前 provider。
func newModelWizard(current model.Config) *modelWizard {
	selected := 0
	for i, option := range modelProviderOptions {
		if option.id == current.Provider {
			selected = i
			break
		}
	}
	return &modelWizard{step: modelWizardProvider, selectedIndex: selected}
}

// selectedProvider 返回当前选中的 provider，并在索引越界时进行纠正。
func (w *modelWizard) selectedProvider() modelProviderOption {
	if w == nil || len(modelProviderOptions) == 0 {
		return modelProviderOption{}
	}
	if w.selectedIndex < 0 {
		w.selectedIndex = 0
	}
	if w.selectedIndex >= len(modelProviderOptions) {
		w.selectedIndex = len(modelProviderOptions) - 1
	}
	return modelProviderOptions[w.selectedIndex]
}

// sessionsLoadedMsg 携带异步加载完成的会话列表。
type sessionsLoadedMsg struct {
	sessions []sessionSummaryItem
	err      error
}

// sessionRestoredMsg 携带历史恢复完成的结果。
type sessionRestoredMsg struct {
	sessionID string
	err       error
}

// fileCompletionLoadedMsg 携带异步加载完成的文件补全列表。
type fileCompletionLoadedMsg struct {
	searchDir string   // 对应的搜索目录，用于丢弃过期结果
	items     []string // 目录内的全部条目（未过滤）
	filtered  []string // 按前缀过滤后的结果
	err       error
}

// sessionSummaryItem 是 session picker 中的一行显示项。
type sessionSummaryItem struct {
	sessionID      string
	createdAt      time.Time
	firstMessage   string
	transcriptSize int64
}

// appModel 是 Bubble Tea TUI 的唯一状态中心。
type appModel struct {
	ctx                 context.Context
	runner              Runner
	sessionID           string
	modelConfig         ModelConfigController
	settingsConfig      SettingsController
	subagents           SubagentController
	sessionStore        SessionStore
	commandRegistry     *CommandRegistry
	queryGuard          QueryGuard
	chatQueue           CommandQueue
	cursorAnchor        *terminalCursorAnchor
	input               textarea.Model
	viewport            viewport.Model
	width               int
	height              int
	ready               bool
	running             bool
	runningTerminal     bool
	terminalMode        bool
	terminalPreview     bool
	showThinking        bool
	selecting           bool
	selectionActive     bool
	selectionStart      selectionPoint
	selectionEnd        selectionPoint
	cursorFrameAt       time.Time
	turnStartedAt       time.Time
	contextMeter        contextMeterAnimation
	pending             []string
	inputHistory        []string
	historyIndex        int
	historyDraft        string
	historyDownLock     bool
	transcript          []transcriptEntry
	activeAssistant     int
	pendingToolCites    []toolCitation
	isGenerating        bool
	lastCtrlCAt         time.Time // 追踪双击 Ctrl+C 退出
	modelWizard         *modelWizard
	settingWizard       *settingWizard
	sessionPicker       *sessionPicker
	completion          *completion
	pipelineState       pipelineState
	pipelineActiveAfter time.Time
	sidebarWidth        int // 右侧面板宽度（字符），由 relayout() 计算并存储
	spinnerFrameIdx     int // 侧边栏 running 条目动画帧索引，由 cursorFrameMsg 驱动
}

// pipelinePhaseStatus 标记单个 pipeline 阶段的状态。
type pipelinePhaseStatus int

const (
	phaseStatusPending pipelinePhaseStatus = iota
	phaseStatusDone
	phaseStatusActive
	phaseStatusRetry
)

// pipelinePhaseEntry 单个阶段的状态快照。
type pipelinePhaseEntry struct {
	name      string
	artifact  string // 相对 .pipeline-workspace/ 的文件名
	status    pipelinePhaseStatus
	iteration int
}

// pipelineState 完整 pipeline 状态快照（每 500ms 轮询更新）。
type pipelineState struct {
	detected   bool // 本次 TUI 会话检测到活跃 pipeline
	activeIdx  int  // 当前 active 阶段索引（-1 = none）
	globalIter int  // 全局迭代（来自 execution-report.json.iteration）
	doneCount  int  // 已完成阶段数
	phases     [18]pipelinePhaseEntry
}

// pipelineStateUpdatedMsg 由后台轮询 cmd 发回，携带最新 pipelineState。
type pipelineStateUpdatedMsg struct {
	state pipelineState
}

type contextStatsProvider interface {
	ContextStats(limitTokens int, draft string) loop.ContextStats
}

package bubble

import (
	"fmt"
	"sort"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// CommandHandler mutates appModel for a slash command and may return a tea.Cmd.
type CommandHandler func(m *appModel, invocation string) tea.Cmd

// Command describes one registered slash command.
type Command struct {
	Name              string
	Aliases           []string
	Description       string
	ArgumentHint      string
	AllowWhileRunning bool
	Handler           CommandHandler
}

// CommandRegistry resolves and dispatches registered slash commands.
type CommandRegistry struct {
	commands map[string]Command
	order    []string
}

// NewCommandRegistry creates the default TUI command registry.
func NewCommandRegistry() *CommandRegistry {
	registry := &CommandRegistry{}
	registry.Register(Command{
		Name:              "/help",
		Description:       "show available commands",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.addEntry(transcriptEntry{kind: entrySystem, title: "help", body: m.commandRegistry.HelpText()})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/model",
		Description:       "open the model switcher",
		ArgumentHint:      "[status|custom|deepseek]",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleModelCommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/export",
		Description:       "export the current conversation",
		ArgumentHint:      "[filename]",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.handleExportCommand(invocation)
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/setting",
		Description:       "open settings wizard",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.settingWizard = newSettingWizard(m.currentSettings())
			m.pending = nil
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/subagent",
		Description:       "launch a subagent",
		ArgumentHint:      "[--fork|--empty] [--background|--sync] <prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleSubagentCommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/streamma",
		Description:       "run a prompt through StreamMA subagents",
		ArgumentHint:      "<prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleStreamMACommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/streamma-trace",
		Description:       "run StreamMA with live event trace",
		ArgumentHint:      "<prompt>",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			return m.handleStreamMACommand(invocation)
		},
	})
	registry.Register(Command{
		Name:              "/tasks",
		Description:       "show background subagent tasks",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.handleTasksCommand()
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/status",
		Description:       "show session status",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			sessionID := m.sessionID
			if sessionID == "" {
				sessionID = "<none>"
			}
			m.addEntry(transcriptEntry{kind: entrySystem, title: "status", body: m.statusText(sessionID)})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/clear",
		Description:       "clear in-process chat history",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			if m.runner != nil {
				m.runner.ResetHistory()
			}
			m.transcript = nil
			m.pending = nil
			m.chatQueue.Clear()
			m.activeAssistant = -1
			m.syncInputMode()
			m.addEntry(transcriptEntry{kind: entrySystem, title: "system", body: "history cleared"})
			return nil
		},
	})
	registry.Register(Command{
		Name:              "/sessions",
		Description:       "browse and restore previous sessions",
		AllowWhileRunning: false,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.sessionPicker = newSessionPicker()
			m.pending = nil
			return loadSessionsCmd(m.ctx, m.sessionStore)
		},
	})
	registry.Register(Command{
		Name:              "/exit",
		Aliases:           []string{"/quit", "exit", "quit"},
		Description:       "quit the TUI",
		AllowWhileRunning: true,
		Handler: func(m *appModel, invocation string) tea.Cmd {
			m.queryGuard.Cancel()
			m.chatQueue.Clear()
			return tea.Quit
		},
	})
	return registry
}

// Register adds or replaces a slash command.
func (r *CommandRegistry) Register(command Command) {
	if r == nil || command.Name == "" || command.Handler == nil {
		return
	}
	if r.commands == nil {
		r.commands = make(map[string]Command)
	}
	name := strings.TrimSpace(command.Name)
	command.Name = name
	if _, exists := r.commands[name]; !exists {
		r.order = append(r.order, name)
	}
	r.commands[name] = command
	for _, alias := range command.Aliases {
		alias = strings.TrimSpace(alias)
		if alias != "" {
			r.commands[alias] = command
		}
	}
}

// Lookup resolves a command token to registered metadata.
func (r *CommandRegistry) Lookup(token string) (Command, bool) {
	if r == nil {
		return Command{}, false
	}
	command, ok := r.commands[strings.TrimSpace(token)]
	return command, ok
}

// Dispatch executes a registered slash command or writes stable feedback for
// malformed and unknown command inputs.
func (r *CommandRegistry) Dispatch(m *appModel, line string) (bool, tea.Cmd) {
	if m == nil || strings.TrimSpace(line) == "" {
		return false, nil
	}
	token := commandToken(line)
	if token == "" || token == "/" {
		m.addEntry(transcriptEntry{kind: entryError, title: "command", body: "invalid slash command"})
		return true, nil
	}

	command, ok := r.Lookup(token)
	if !ok {
		m.addEntry(transcriptEntry{kind: entryError, title: "command", body: fmt.Sprintf("unknown command: %s", token)})
		return true, nil
	}
	if m.isWorkRunning() && !command.AllowWhileRunning {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: fmt.Sprintf("%s is unavailable while a turn is running", token)})
		return true, nil
	}
	return true, command.Handler(m, line)
}

// HelpText renders command metadata in a deterministic order.
func (r *CommandRegistry) HelpText() string {
	if r == nil {
		return "No commands registered."
	}
	names := append([]string(nil), r.order...)
	sort.Strings(names)
	lines := []string{"Commands:"}
	for _, name := range names {
		command, ok := r.commands[name]
		if !ok {
			continue
		}
		label := command.Name
		if strings.TrimSpace(command.ArgumentHint) != "" {
			label += " " + strings.TrimSpace(command.ArgumentHint)
		}
		if len(command.Aliases) > 0 {
			aliases := append([]string(nil), command.Aliases...)
			sort.Strings(aliases)
			label += " (" + strings.Join(aliases, ", ") + ")"
		}
		lines = append(lines, fmt.Sprintf("%s - %s", label, command.Description))
	}
	lines = append(lines, "Type ! to toggle terminal mode or !<command> to run bash once.")
	return strings.Join(lines, "\n")
}

func commandToken(line string) string {
	line = strings.TrimSpace(line)
	if line == "" {
		return ""
	}
	fields := strings.Fields(line)
	if len(fields) == 0 {
		return line
	}
	return fields[0]
}

func (m *appModel) handleStreamMACommand(invocation string) tea.Cmd {
	invocation = strings.TrimSpace(invocation)
	task := strings.TrimSpace(strings.TrimPrefix(invocation, commandToken(invocation)))
	if task == "" {
		if commandToken(invocation) == "/streamma-trace" {
			m.addEntry(transcriptEntry{
				kind:  entrySystem,
				title: "streamma-trace",
				body:  "usage: /streamma-trace <prompt>\nRuns the same StreamMA DAG and prints live runtime events for step fanout inspection.",
			})
			return nil
		}
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "streamma",
			body:  "usage: /streamma <prompt>\nRuns an adaptive StreamMA DAG with real subagent workers and END_STEP step exchange.",
		})
		return nil
	}
	m.rememberInputHistory(invocation)
	updated, cmd := m.startChatTurn(invocation)
	*m = updated
	return cmd
}

